    Bug 2016020 - Enable allow_executeScript_in_moz_extension to restore old content script behavior. r=mkmelin

    Restoring the old behavior to allow this test to pass. There is more work
    needed in a follow-up, to make this test pass with the newly introduced
    restrictions (without setting the pref).

    Differential Revision: https://phabricator.services.mozilla.com/D282760

diff --git a/mail/components/extensions/test/browser/browser_ext_tabs_content.js b/mail/components/extensions/test/browser/browser_ext_tabs_content.js
index d420f4a8f14..d11683a5e21 100644
--- a/mail/components/extensions/test/browser/browser_ext_tabs_content.js
+++ b/mail/components/extensions/test/browser/browser_ext_tabs_content.js
@@ -4,6 +4,18 @@

 "use strict";

+add_setup(function () {
+  Services.prefs.setBoolPref(
+    "extensions.webextensions.allow_executeScript_in_moz_extension",
+    true
+  );
+  registerCleanupFunction(async () => {
+    Services.prefs.clearUserPref(
+      "extensions.webextensions.allow_executeScript_in_moz_extension"
+    );
+  });
+});
+
